function score(p,x){let s=0,why=[],miss=[],info=[];
 if(p.int.includes(x.c)){s+=30;why.push("Область совпадает с вашими интересами (+30)")}else miss.push("Область не входит в ваши интересы");
 if(p.str.includes(x.c)){s+=20;why.push("Это один из ваших сильнейших предметов (+20)")}
 if(p.age>=x.a&&p.age<=x.b){s+=20;why.push("Ваш возраст попадает в ориентировочный диапазон "+x.a+"–"+x.b+" (+20)")}else miss.push("Ориентировочный возраст: "+x.a+"–"+x.b+" лет");
 if(p.eng>=x.e){s+=15;why.push("Ваш уровень английского соответствует ориентиру (+15)")}else miss.push("Ориентир по английскому: «"+ENG[x.e]+"»");
 if(p.fmt==="Любой"||FMT[x.f]===p.fmt||x.f==="С"){s+=15;why.push("Формат участия подходит (+15)")}else miss.push("Формат: "+FMT[x.f]+", вы предпочитаете "+p.fmt.toLowerCase());
 if(p.bud==="Только бесплатно"&&x.p!=="F")info.push("Стоимость зависит от условий выбранной программы");
 if(x.f==="Ч")info.push("Очный формат может требовать поездки; учитывайте логистику поездки");
 return{x,s,why,miss,info}}
